// ---------- TestCCacheCache_GetSet ----------

func TestCCacheCache_GetSet(t *testing.T) {
	c := NewCCacheCache(100)

	tests := []struct {
		name   string
		bucket string
		key    string
		entry  CacheEntry
	}{
		{
			name:   "basic entry",
			bucket: "b1",
			key:    "k1",
			entry:  CacheEntry{LastUpdate: 100, Value: 42},
		},
		{
			name:   "zero value",
			bucket: "b1",
			key:    "k2",
			entry:  CacheEntry{LastUpdate: 0, Value: 0},
		},
		{
			name:   "different bucket same key",
			bucket: "b2",
			key:    "k1",
			entry:  CacheEntry{LastUpdate: 200, Value: 99},
		},
		{
			name:   "large values",
			bucket: "b3",
			key:    "large",
			entry:  CacheEntry{LastUpdate: 1<<62 - 1, Value: 1<<64 - 1},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c.Set(tt.bucket, tt.key, tt.entry, time.Hour)

			got, ok := c.Get(tt.bucket, tt.key)
			if !ok {
				t.Fatalf("Get(%q, %q): ok=false, want true", tt.bucket, tt.key)
			}
			if got != tt.entry {
				t.Errorf("Get(%q, %q) = %+v, want %+v", tt.bucket, tt.key, got, tt.entry)
			}
		})
	}
}

// ---------- TestCCacheCache_Get_NotFound ----------

func TestCCacheCache_Get_NotFound(t *testing.T) {
	c := NewCCacheCache(100)

	tests := []struct {
		name   string
		bucket string
		key    string
	}{
		{name: "empty cache", bucket: "b", key: "k"},
		{name: "nonexistent bucket", bucket: "nobucket", key: "k"},
		{name: "existing bucket wrong key", bucket: "b", key: "missing"},
	}

	// pre-populate one entry so we can test "wrong key in existing bucket"
	c.Set("b", "exists", CacheEntry{LastUpdate: 1, Value: 1}, time.Hour)

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, ok := c.Get(tt.bucket, tt.key)
			if ok {
				t.Errorf("Get(%q, %q): ok=true, want false; got=%+v", tt.bucket, tt.key, got)
			}
		})
	}
}

// ---------- TestCCacheCache_Iterator ----------

func TestCCacheCache_Iterator(t *testing.T) {
	c := NewCCacheCache(100)

	entries := map[string]CacheEntry{
		"a": {LastUpdate: 1, Value: 10},
		"b": {LastUpdate: 2, Value: 20},
		"c": {LastUpdate: 3, Value: 30},
	}
	for k, v := range entries {
		c.Set("bucket", k, v, time.Hour)
	}

	// collect all entries from the iterator
	collected := make(map[string]CacheEntry)
	for k, v := range c.Iterator("bucket") {
		collected[k] = v
	}

	if len(collected) != len(entries) {
		t.Fatalf("iterator yielded %d entries, want %d", len(collected), len(entries))
	}
	for k, want := range entries {
		got, ok := collected[k]
		if !ok {
			t.Errorf("iterator: missing key %q", k)
			continue
		}
		if got != want {
			t.Errorf("iterator[%q] = %+v, want %+v", k, got, want)
		}
	}
}

