func TestCCacheCache_Iterator_EarlyStop(t *testing.T) {
	c := NewCCacheCache(100)

	for i := 0; i < 5; i++ {
		c.Set("b", string(rune('a'+i)), CacheEntry{Value: uint64(i)}, time.Hour)
	}

	count := 0
	for range c.Iterator("b") {
		count++
		if count >= 2 {
			// Stop early; ForEachFunc returns false when yield returns false
			break
		}
	}
	// we stopped after 2, so we should not have iterated all 5
	if count != 2 {
		t.Errorf("early stop count = %d, want 2", count)
	}
}

// ---------- TestCCacheCache_TTLExpiry ----------

func TestCCacheCache_TTLExpiry(t *testing.T) {
	c := NewCCacheCache(100)

	c.Set("b", "expires", CacheEntry{LastUpdate: 1, Value: 99}, 10*time.Millisecond)

	// should be available immediately
	got, ok := c.Get("b", "expires")
	if !ok || got.Value != 99 {
		t.Fatalf("immediate Get: ok=%v, got=%+v, want ok=true with Value=99", ok, got)
	}

	// wait for TTL to pass (plus some buffer for internal cleanup)
	time.Sleep(50 * time.Millisecond)

	got, ok = c.Get("b", "expires")
	if ok {
		t.Errorf("Get after TTL: ok=true, want false; got=%+v", got)
	}

	// iterator should not yield the expired entry
	for k, v := range c.Iterator("b") {
		t.Errorf("iterator yielded expired entry: %q => %+v", k, v)
	}
}

func TestCCacheCache_TTLExpiry_NotExpired(t *testing.T) {
	c := NewCCacheCache(100)

	c.Set("b", "fresh", CacheEntry{Value: 7}, 10*time.Second)
	time.Sleep(10 * time.Millisecond)

	got, ok := c.Get("b", "fresh")
	if !ok {
		t.Error("Get should succeed before TTL elapses")
	}
	if got.Value != 7 {
		t.Errorf("Get Value = %d, want 7", got.Value)
	}
}

// ---------- TestCCacheCache_MaxSizeEviction ----------

func TestCCacheCache_MaxSizeEviction(t *testing.T) {
	// small cache: max 2 items total
	c := NewCCacheCache(2)

	// insert many entries to force eviction, then verify total count ≤ MaxSize
	for i := 0; i < 10; i++ {
		c.Set("b", string(rune('a'+i)), CacheEntry{Value: uint64(i)}, time.Hour)
	}

	// Give the background eviction worker a moment
	time.Sleep(5 * time.Millisecond)

	// Count items via iterator — should be at most MaxSize
	count := 0
	for range c.Iterator("b") {
		count++
	}
	if count > 2 {
		t.Errorf("iterator count = %d, want ≤ 2 (MaxSize eviction)", count)
	}
	if count == 0 {
		t.Error("iterator count = 0, cache is unexpectedly empty")
	}
}

func TestCCacheCache_MaxSizeEviction_DifferentBuckets(t *testing.T) {
	// max 2 items per bucket — different buckets have independent limits
	c := NewCCacheCache(2)

	c.Set("b1", "k1", CacheEntry{Value: 1}, time.Hour)
	c.Set("b1", "k2", CacheEntry{Value: 2}, time.Hour)
	c.Set("b2", "k1", CacheEntry{Value: 3}, time.Hour)
	c.Set("b2", "k2", CacheEntry{Value: 4}, time.Hour)

	// both buckets hold 2 items each — no eviction should have occurred
	for _, bucket := range []string{"b1", "b2"} {
		for _, key := range []string{"k1", "k2"} {
			if _, ok := c.Get(bucket, key); !ok {
				t.Errorf("bucket %q key %q: Get returned ok=false, want true", bucket, key)
			}
		}
	}
}

// ---------- TestCCacheCache_GetSet_Overwrite ----------

func TestCCacheCache_GetSet_Overwrite(t *testing.T) {
	c := NewCCacheCache(100)

	c.Set("b", "k", CacheEntry{LastUpdate: 1, Value: 100}, time.Hour)
	c.Set("b", "k", CacheEntry{LastUpdate: 2, Value: 200}, time.Hour)

	got, ok := c.Get("b", "k")
	if !ok {
		t.Fatal("Get returned ok=false after overwrite")
	}
	if got.Value != 200 || got.LastUpdate != 2 {
		t.Errorf("Get = %+v, want {LastUpdate:2 Value:200}", got)
	}
}

// ---------- Race detection ----------

func TestCCacheCache_ConcurrentAccess(t *testing.T) {
	c := NewCCacheCache(100)
	done := make(chan struct{})

	go func() {
		for i := 0; i < 100; i++ {
			c.Set("b", "k", CacheEntry{Value: uint64(i)}, time.Hour)
			c.Get("b", "k")
		}
		done <- struct{}{}
	}()
	go func() {
		for i := 0; i < 100; i++ {
			c.Set("b", "k", CacheEntry{Value: uint64(i)}, time.Hour)
			c.Get("b", "k")
		}
		done <- struct{}{}
	}()
	<-done
	<-done
}
